def bind(path):
    path=Path(path).resolve();raw=path.read_bytes()
    return {'path':str(path.relative_to(ROOT)),'sha256':'sha256:'+hashlib.sha256(raw).hexdigest(),'bytes':len(raw)}
def h(v):return 'sha256:'+hashlib.sha256(json.dumps(v,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest()
def write(name,value):
    p=OWN/name;assert not p.exists(),name
    p.write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n')
def textwrite(name,value):
    p=OWN/name;assert not p.exists(),name;p.write_text(value)
